-- 011430be English: your primary talent tree {{!is|is not}} %s
[3649] = "Ihr primärer Talentbaum {{!ist|ist nicht}} %s",
-- 1ebc1187 English: the zone's PVP status {{!is|is not}} %s
[3650] = "Der PvP-Status der Zone {{!ist|ist nicht}} %s",
-- 0bcca767 English: {{!in|not in}} {zone}
[3651] = "{{!in|nicht in}} {zone}",
-- c14661e2 English: Time in combat
[3652] = "Zeit im Kampf",
-- 33629208 English: %s {{!is|is not}} auto-repeating
[3653] = "%s {{!wird|wird nicht}} automatisch wiederholt",
-- 9544d41a English: Tests whether the selected spell is currently auto-repeating, such as Shoot or
--     Auto Shot. This is different from a spell being current or queued: a queued cast alone does
--     not satisfy this condition. Unavailable client observations remain unavailable even when
--     negated.
[3654] = "Prüft, ob der gewählte Zauber gerade automatisch wiederholt wird, etwa Schießen oder Automatischer Schuss. Das ist etwas anderes, als dass ein Zauber aktuell oder eingereiht ist: Ein eingereihter Zauber allein erfüllt diese Bedingung nicht. Nicht verfügbare Client-Beobachtungen bleiben auch bei Negation nicht verfügbar.",
-- 32d5dd3a English: Uses readable positions in the same instance, or player-centered range
--     estimates when positions are unavailable. A unit counts only when its upper range bound is
--     within Distance. Uncertain positions, range, subgroup membership or required health/mana
--     values keep the whole condition unavailable, including under Unless. Percentage checks
--     require a positive maximum; empty aggregates have no result.
[3655] = "Verwendet lesbare Positionen in derselben Instanz oder, wenn keine Positionen verfügbar sind, spielerzentrierte Reichweitenschätzungen. Eine Einheit zählt nur, wenn die Obergrenze ihrer Reichweite innerhalb von „Entfernung“ liegt. Unsichere Positionen, Reichweiten, Untergruppenzugehörigkeit oder benötigte Gesundheits-/Manawerte machen die gesamte Bedingung nicht verfügbar, auch unter „Außer wenn“. Prozentprüfungen erfordern ein positives Maximum; leere Aggregate liefern kein Ergebnis.",
-- 4953738e English: Count enemies when selected, or non-enemies when cleared.
[3656] = "Ausgewählt: Feinde zählen; abgewählt: Nicht-Feinde zählen.",
-- 5179228a English: The number of observed units proven within Distance of you.
[3657] = "Die Anzahl beobachteter Einheiten, die sich nachweislich innerhalb von „Entfernung“ zu Ihnen befinden.",
-- 5f3da9f5 English: Counts the addon's observed unit snapshot, including nameplates and tracked
--     unit aliases, rather than every nearby unit. A unit counts only when its upper range bound is
--     within Distance; uncertain membership or unreadable identity, hostility, range or nameplate
--     settings makes the whole count unavailable, including under Unless. Known vanished or reused
--     unit tokens are excluded. Distance cannot exceed the current nameplate distance setting; that
--     setting does not guarantee a complete scan.
[3658] = "Zählt die beobachtete Einheiten-Momentaufnahme des Addons, einschließlich Namensplaketten und verfolgter Einheiten-Aliasse, nicht jede Einheit in der Nähe. Eine Einheit zählt nur, wenn die Obergrenze ihrer Reichweite innerhalb von „Entfernung“ liegt; unsichere Zugehörigkeit oder nicht lesbare Identität, Feindseligkeit, Reichweite oder Namensplaketten-Einstellungen machen die gesamte Zählung nicht verfügbar, auch unter „Außer wenn“. Bekanntermaßen verschwundene oder wiederverwendete Einheitenkennungen werden ausgeschlossen. „Entfernung“ kann die aktuelle Einstellung der Namensplakettenentfernung nicht überschreiten; diese Einstellung garantiert keine vollständige Erfassung.",
-- 60bfbfa2 English: you {{!have|do not have}} {item} equipped
[3659] = "{item} {{!ist|ist nicht}} angelegt",
-- 1d06a92b English: {item} {{!is|is not}} available{carrying}
[3660] = "{item} {{!ist|ist nicht}} verfügbar{carrying}",
-- ac058958 English: {item} {{!is|is not}} in range{carrying}
[3661] = "{item} {{!ist|ist nicht}} in Reichweite{carrying}",
-- 216e438b English: the cooldown on {item} {comparison} {duration}{carrying}
[3662] = "die Abklingzeit von {item} {comparison} {duration}{carrying}",
-- 623bd8c4 English: {unit} {{!is|is not}} in a group
[3663] = "{unit} {{!ist|ist nicht}} in einer Gruppe",
-- fedfc418 English: {unit} {{!is friendly to you|is not friendly to you}}
[3664] = "{unit} {{!ist Ihnen gegenüber freundlich|ist Ihnen gegenüber nicht freundlich}}",
-- 6e21eee4 English: Matches when the selected unit is dead or a ghost. A missing or unreadable unit
--     is unavailable, including under NOT. In a Via Macro announcement, choose Announcement target
--     to follow the supplied unit.
[3665] = "Trifft zu, wenn die gewählte Einheit tot oder ein Geist ist. Eine fehlende oder nicht lesbare Einheit ist nicht verfügbar, auch unter NOT. In einer „Per Makro“-Ankündigung „Ankündigungsziel“ wählen, um der übergebenen Einheit zu folgen.",
-- eaa8232a English: Matches when the game reports the selected unit as friendly to you. This does
--     not imply party or raid membership. A missing or unreadable unit is unavailable.
[3666] = "Trifft zu, wenn das Spiel die gewählte Einheit als Ihnen gegenüber freundlich meldet. Das bedeutet keine Gruppen- oder Schlachtzugsmitgliedschaft. Eine fehlende oder nicht lesbare Einheit ist nicht verfügbar.",
-- b9151b16 English: Assisted Combat {{!is|is not}} suggesting a spell
[3667] = "Der Kampfassistent {{!schlägt einen Zauber vor|schlägt keinen Zauber vor}}",
-- 43bf497e English: Assisted Combat {{!suggests|does not suggest}} %s
[3668] = "Der Kampfassistent {{!schlägt|schlägt nicht}} %s vor",
-- 6c9594a9 English: Matches when Blizzard's Assisted Combat suggests this spell as the next cast.
--     An override counts as its base spell, and the base spell as its override. With no spell
--     chosen, matches whenever Assisted Combat suggests anything.
[3669] = "Trifft zu, wenn Blizzards Kampfassistent diesen Zauber als nächsten Zauber vorschlägt. Eine Überschreibung zählt als ihr Basiszauber und der Basiszauber als seine Überschreibung. Ohne gewählten Zauber trifft es zu, sobald der Kampfassistent irgendetwas vorschlägt.",
-- 44e850ce English: Assisted Combat exists on Retail (and is declared on Forever). Where the game
--     does not offer it, for this character or specialization, or the suggestion cannot be read,
--     this condition is unavailable rather than false, including under NOT.
[3670] = "Den Kampfassistenten gibt es in Retail (unter Forever ist er angekündigt). Wo das Spiel ihn für diesen Charakter oder diese Spezialisierung nicht anbietet oder der Vorschlag nicht gelesen werden kann, ist diese Bedingung nicht verfügbar statt falsch, auch unter NOT.",
-- 32c737f7 English: %s {{!is|is not}} in Blizzard's Assisted Combat rotation
[3671] = "%s {{!ist|ist nicht}} in Blizzards Kampfassistent-Rotation",
-- ae726224 English: Matches when this spell is one Blizzard's Assisted Combat can suggest for your
--     current specialization. Its current override and its base spell count too. Use it to
--     highlight what Assisted Combat leaves out, for example a cooldown that is not in the set.
[3672] = "Trifft zu, wenn dieser Zauber einer ist, den Blizzards Kampfassistent für Ihre aktuelle Spezialisierung vorschlagen kann. Seine aktuelle Überschreibung und sein Basiszauber zählen ebenfalls. Verwenden Sie sie, um hervorzuheben, was der Kampfassistent auslässt, zum Beispiel eine Abklingzeit, die nicht in der Menge enthalten ist.",
-- 2a9b9d24 English: The set is read again whenever your spells change, never guessed. Where the
--     game does not offer Assisted Combat for this character or specialization, or the set cannot
--     be read, this condition is unavailable rather than false, including under NOT.
[3673] = "Die Menge wird bei jeder Änderung Ihrer Zauber neu gelesen, nie geraten. Bietet das Spiel den Kampfassistenten für diesen Charakter oder diese Spezialisierung nicht an oder ist die Menge nicht lesbar, ist diese Bedingung nicht verfügbar statt nicht erfüllt, auch unter NOT.",
-- 10ac60e3 English: Assisted Combat {{!is|is not}} available
[3674] = "Der Kampfassistent {{!ist|ist nicht}} verfügbar",
-- d882c8a9 English: Matches when the game offers Blizzard's Assisted Combat for your character and
--     current specialization. When it does not (for example a specialization Blizzard has no
--     Assisted Combat rotation for, or a client that declares the API but does not offer the
--     feature), this is false, so a branch can fall back to your own steps.
[3675] = "Trifft zu, wenn das Spiel Blizzards Kampfassistenten für Ihren Charakter und Ihre aktuelle Spezialisierung anbietet. Tut es das nicht (zum Beispiel bei einer Spezialisierung, für die Blizzard keine Kampfassistent-Rotation hat, oder bei einem Client, der die API deklariert, aber die Funktion nicht anbietet), ist sie nicht erfüllt, sodass ein Zweig auf Ihre eigenen Schritte zurückfallen kann.",
-- 65331c0d English: Unavailable only where the client has no Assisted Combat API or its answer
--     cannot be read, including under NOT.
[3676] = "Nur nicht verfügbar, wenn der Client keine Kampfassistent-API hat oder seine Antwort nicht lesbar ist, auch unter NOT.",
-- 6f6ccc8f English: rune spell %s
[3677] = "Runenzauber %s",
-- 7bf70ccc English: rune %s
[3678] = "Rune %s",
-- 54791384 English: you {{!have|do not have}} the rune %s engraved
[3679] = "die Rune %s {{!ist|ist nicht}} eingraviert",
-- e999d0a1 English: <rune>
[3680] = "<Rune>",
-- 4e0d82c9 English: Your runes have not loaded yet. Reopen this condition shortly, or enter an ID
--     below.
[3681] = "Ihre Runen sind noch nicht geladen. Öffnen Sie diese Bedingung in Kürze erneut oder geben Sie unten eine ID ein.",
-- 1327b43b English: This character cannot engrave runes. A rune entered by ID below is kept, and is
--     unavailable here.
[3682] = "Dieser Charakter kann keine Runen eingravieren. Eine unten per ID eingegebene Rune bleibt erhalten und ist hier nicht verfügbar.",
-- 7294ffa8 English: Slot %d
[3683] = "Platz %d",
