[3686] = "Runenzauber-ID",
-- b84ca6e3 English: Rune ID
[3687] = "Runen-ID",
-- a698651e English: Matches when a Season of Discovery rune is engraved on one of your equipped
--     items. Passive runes count too, which a known-spell test cannot see.
[3688] = "Trifft zu, wenn eine Rune aus Season of Discovery in einen Ihrer angelegten Gegenstände eingraviert ist. Passive Runen zählen ebenfalls, was ein Test auf bekannte Zauber nicht sehen kann.",
-- 1daa202b English: Pick one of your known runes by equipment slot. The rune is saved by the first
--     spell it teaches, so a shared rotation names it on any character.
[3689] = "Wählen Sie eine Ihrer bekannten Runen nach Ausrüstungsplatz. Die Rune wird über den ersten Zauber gespeichert, den sie lehrt, daher benennt eine geteilte Rotation sie auf jedem Charakter.",
-- 8151a8cf English: Enter a spell the rune teaches, or the rune's own ID (its skill line ability
--     ID) for a rune that teaches no spell. Entering one clears the other.
[3690] = "Geben Sie einen Zauber ein, den die Rune lehrt, oder die eigene ID der Rune (ihre Fertigkeitslinien-Fähigkeits-ID) für eine Rune, die keinen Zauber lehrt. Die Eingabe des einen löscht den anderen.",
-- 868afb4d English: Engraving exists only on Season of Discovery realms. Elsewhere, and until your
--     runes have loaded after logging in, this condition is unavailable rather than false,
--     including under NOT. The Phase 7 shoulder runes are not engravings and are not seen. This is
--     not the Death Knight Rune condition.
[3691] = "Gravuren gibt es nur auf Realms von Season of Discovery. Anderswo und bis Ihre Runen nach der Anmeldung geladen sind, ist diese Bedingung nicht verfügbar statt nicht erfüllt, auch unter NOT. Die Schulterrunen aus Phase 7 sind keine Gravuren und werden nicht erkannt. Dies ist nicht die Bedingung Rune der Todesritter.",
-- 2cfaca8e English: Your talents cannot be listed right now (%s). A node ID entered below is kept
--     and evaluated.
[3692] = "Deine Talente können gerade nicht aufgelistet werden (%s). Eine unten eingegebene Knoten-ID bleibt erhalten und wird ausgewertet.",
-- 0d2b4c68 English: Talents can be listed only for your own class. A node ID entered below is kept
--     and evaluated.
[3693] = "Talente lassen sich nur für deine eigene Klasse auflisten. Eine unten eingegebene Knoten-ID bleibt erhalten und wird ausgewertet.",
